<script>document.addEventListener('DOMContentLoaded',()=>{const filters=document.querySelectorAll('.gallery-filter'),items=document.querySelectorAll('.gallery-item'),box=document.getElementById('gallery-lightbox'),image=document.getElementById('lightbox-image'),title=document.getElementById('lightbox-title');filters.forEach(button=>button.addEventListener('click',()=>{const filter=button.dataset.filter;filters.forEach(b=>b.classList.remove('bg-stone-900','text-white'));button.classList.add('bg-stone-900','text-white');items.forEach(item=>item.classList.toggle('hidden',filter!=='all'&&item.dataset.category!==filter));}));items.forEach(item=>item.addEventListener('click',()=>{image.src=item.dataset.src;image.alt=item.dataset.title;title.textContent=item.dataset.title;box.classList.remove('hidden');box.classList.add('flex');}));const close=()=>{box.classList.add('hidden');box.classList.remove('flex');image.src='';};document.getElementById('lightbox-close').addEventListener('click',close);box.addEventListener('click',event=>{if(event.target===box)close();});document.addEventListener('keydown',event=>{if(event.key==='Escape')close();});});</script>
